class Solution:
    def minimizeConcatenation(self, words: List[str]) -> int:
        INF = float('inf')
        dp = {(words[0][0], words[0][-1]): len(words[0])}
        for w in words[1:]:
            f, l, wl = w[0], w[-1], len(w)
            ndp = {}
            for (pf, pl), L in dp.items():
                v1 = L + wl - (pl == f)
                k1 = (pf, l)
                if ndp.get(k1, INF) > v1: ndp[k1] = v1
                v2 = L + wl - (lw == pf)
                k2 = (f, pl)
                if ndp.get(k2, INF) > v2: ndp[k2] = v2
            dp = ndp
        return min(dp.values())

