class Solution {
public:
    int minimizeConcatenation(vector<string>& words) {
        unordered_map<string,int> dp;
        string k0; k0 += words[0][0]; k0 += words[0].back();
        dp[k0] = words[0].size();
        for (int i = 1; i < (int)words.size(); i++) {
            char f = words[i][0], l = words[i].back();
            int wl = words[i].size();
            unordered_map<string,int> ndp;
            for (auto& [key, L] : dp) {
                char pf = key[0], pl = key[1];
                auto upd = [&](string nk, int v) {
                    if (!ndp.count(nk) || ndp[nk] > v) ndp[nk] = v;
                };
                upd(string{pf, l}, L + wl - (pl == f));
                upd(string{f, pl}, L + wl - (l == pf));
            }
            dp = move(ndp);
        }
        int ans = INT_MAX;
        for (auto& [k, v] : dp) ans = min(ans, v);
        return ans;
    }
};

