class Solution {
    public int minimizeConcatenation(String[] words) {
        Map<String, Integer> dp = new HashMap<>();
        dp.put("" + words[0].charAt(0) + words[0].charAt(words[0].length()-1), words[0].length());
        for (int i = 1; i < words.length; i++) {
            char f = words[i].charAt(0), l = words[i].charAt(words[i].length()-1);
            int wl = words[i].length();
            Map<String, Integer> ndp = new HashMap<>();
            for (var e : dp.entrySet()) {
                char pf = e.getKey().charAt(0), pl = e.getKey().charAt(1);
                int L = e.getValue();
                String k1 = "" + pf + l, k2 = "" + f + pl;
                ndp.merge(k1, L + wl - (pl == f ? 1 : 0), Math::min);
                ndp.merge(k2, L + wl - (l == pf ? 1 : 0), Math::min);
            }
            dp = ndp;
        }
        int ans = Integer.MAX_VALUE;
        for (int v : dp.values()) ans = Math.min(ans, v);
        return ans;
    }
}

