class Solution:
    def minimizeConcatenation(self, words: List[str]) -> int:
        f, l, L = words[0][0], words[0][-1], len(words[0])
        for w in words[1:]:
            wf, wl_, wlen = w[0], w[-1], len(w)
            save_append = 1 if l == wf else 0
            save_prepend = 1 if wl_ == f else 0
            if save_append >= save_prepend:
                L += wlen - save_append; l = wl_
            else:
                L += wlen - save_prepend; f = wf
        return L

