class Solution {
public:
    int minimizeConcatenation(vector<string>& words) {
        char f = words[0][0], l = words[0].back();
        int L = words[0].size();
        for (int i = 1; i < (int)words.size(); i++) {
            char wf = words[i][0], wl_ = words[i].back();
            int sa = (l == wf), sp = (wl_ == f);
            if (sa >= sp) { L += (int)words[i].size() - sa; l = wl_; }
            else { L += (int)words[i].size() - sp; f = wf; }
        }
        return L;
    }
};

